pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
    }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));
        assertTrue(ok, "deposit to initialized contract with valid log must succeed");
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function runTest(uint256 amount) public payable {
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        assert(c.balances(address(this)) == amount);
    }
    receive() external payable {}
    fallback() external payable {}
}

