contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint val) public payable {
        require(val < 2**256 - 1, true);
        c.SetMinSum(val); // allowed only before initialization in P
        c.Initialized();  // top-level: mark contract as initialized
        bool reverted;
        try c.SetMinSum(val) { reverted = false; } catch { reverted = true; }   // boundary
        assert(reverted); // once initialized, SetMinSum must always revert (P), mutant lets it through
    }
    receive() external payable {}
}

